/* Generated by scripts/knowledge-library-build.mjs from docs/knowledge/foundational-library-v0.1.md — do not edit by hand. */
export const KNOWLEDGE_LIBRARY_V1 = {"library":"foundational","version":1,"builtFrom":"docs/knowledge/foundational-library-v0.1.md","lastReviewed":"2026-10-08","entries":[{"id":"demand-search-signals","version":1,"category":"demand-validation","title":"Read demand from search and autocomplete before building","body":"Before making anything, collect evidence that people are already looking for it. Sources:\n- Google autocomplete, \"People also ask\" and related searches\n- Marketplace search suggestions on Etsy and Gumroad Discover\n- Free keyword tools\n- Questions that keep recurring in forums\n\nStrong signals:\n- Specific, problem-shaped queries with buying intent, such as \"invoice template for UK sole trader\", rather than broad topics like \"templates\".\n- Several existing paid products, which shows people pay.\n- Weak or out-of-date competitors.\n\nWrite down the query, where you saw it, and a rough volume or competition note in the experiment log. Drop ideas with no searches and no paid competitors. Treat \"no competitors\" as a warning sign, not an opportunity. Spend no more than about one working session on this per idea.","tags":["demand","keyword-research","autocomplete","validation","niche"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://developers.google.com/search/docs/fundamentals/seo-starter-guide (Google docs: generally CC BY 4.0 text. Paraphrase with attribution.)","urls":["https://developers.google.com/search/docs/fundamentals/seo-starter-guide"],"licence":"Google docs: generally CC BY 4.0 text. Paraphrase with attribution.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"demand-marketplace-bestsellers","version":1,"category":"demand-validation","title":"Mine marketplace bestsellers and reviews for gaps","body":"Open the top 20 listings for your target query on Etsy, Gumroad Discover or Payhip. For each, record:\n- price\n- review count, and its age if visible\n- format\n- what buyers praise and what they complain about\n\nThree- and four-star reviews tell you the most, because they show unmet needs such as \"wish it had a UK version\" or \"hard to edit on mobile\". Pick a niche where demand is proven (many reviews) and a specific weakness is repeated. Then position your product directly against that weakness.\n\nNever copy listing text, images or files. Record only the facts and your own observations.","tags":["competitor-research","reviews-mining","etsy","gumroad-discover","gap"],"keywords":[],"factsThatChange":[{"fact":"marketplace search and ranking behaviour changes often. UNVERIFIED as to current ranking factors.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":["Never copy listing text, images or files. Record only the facts and your own observations."],"sources":[{"text":"- https://help.etsy.com/hc/en-us/articles/360024112614 (platform help page: facts paraphrased, link only)","urls":["https://help.etsy.com/hc/en-us/articles/360024112614"],"licence":"platform help page: facts paraphrased, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"validate-presell-smoke-test","version":1,"category":"demand-validation","title":"Pre-sell or smoke-test before full production","body":"Cheapest test first:\n1. A landing page or listing that describes the product, with a real price and a \"buy\" or \"join waitlist\" button.\n2. A preview (sample page or screenshot) that you actually made.\n\nPre-selling is lawful only if the listing honestly states the delivery date and you refund promptly if you don't deliver. Never take payment for something you cannot deliver.\n\nSet success thresholds in advance, for example \"3 pre-orders or 30 waitlist sign-ups from 300 targeted visitors within 14 days\". If you miss the threshold, change one variable (headline, price or audience) once. Then stop.\n\nWaitlist emails need consent for marketing (see email-list-pecr-gdpr).","tags":["pre-sale","landing-page","waitlist","smoke-test","threshold"],"keywords":[],"factsThatChange":[{"fact":"some platforms restrict pre-orders or non-delivered products. Check the platform's terms (UNVERIFIED for each platform).","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":[],"sources":[{"text":"- https://www.gov.uk/online-and-distance-selling-for-businesses (UK government: Open Government Licence v3.0. Paraphrase with attribution.)","urls":["https://www.gov.uk/online-and-distance-selling-for-businesses"],"licence":"UK government: Open Government Licence v3.0. Paraphrase with attribution.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"validate-define-experiment","version":1,"category":"demand-validation","title":"Run every idea as a bounded experiment","body":"Every idea gets an experiment record before you spend anything:\n- hypothesis (who will buy what, at what price, and why)\n- cost cap in money and hours\n- time box (7–21 days)\n- leading metric (visits, add-to-cart, email sign-ups)\n- success threshold\n- kill condition\n\nOnly one primary variable changes per iteration. At the deadline, record the outcome as continue, pivot or stop, and say why. Unbounded \"keep tweaking\" is the most common way to burn runway. Write down what you learned even when the experiment fails, because the next agent can reuse it.","tags":["experiment","hypothesis","time-box","kill-condition","budget"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"internal method; no external source needed.","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"format-templates-spreadsheets","version":1,"category":"product-formats-pricing","title":"Templates and spreadsheets: sell an outcome, not a file","body":"The formats that sell best solve a recurring, painful admin job: budgets, invoices, trackers, planners, checklists and SOPs. Name the outcome in the title, for example \"Track UK self-employed expenses in 10 minutes a week\".\n\nDeliver:\n- the file in common formats (Google Sheets copy link, Excel, sometimes Numbers)\n- a one-page quick-start\n- an example filled with clearly fictional data\n\nTest every formula and lock or protect the formula cells. Localise for the audience (UK tax-year dates, £, date format). Do not give tax, legal or financial advice inside the template (see legal-no-regulated-advice); give tools and point to official guidance.","tags":["template","spreadsheet","google-sheets","excel","tracker"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.gov.uk/self-employed-records (UK government: OGL v3.0. Paraphrase with attribution. Useful for UK-accurate structure only.)","urls":["https://www.gov.uk/self-employed-records"],"licence":"UK government: OGL v3.0. Paraphrase with attribution. Useful for UK-accurate structure only.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"format-notion-digital-planners-printables","version":1,"category":"product-formats-pricing","title":"Notion templates, printables and planners","body":"- **Notion templates:** deliver a duplicate link, include setup steps, and say which Notion plan is needed.\n- **Printables:** provide A4 and US Letter PDFs and say exactly what is included (page count, sizes).\n- **Digital planners:** state which apps are compatible.\n\nShow real screenshots of the actual product; do not use mock-ups that misrepresent it. These markets are crowded, so win on a narrow audience (\"planner for UK nursing students on placement\") rather than on generic aesthetics. If AI tools were used to make images or text, disclose it where the platform requires (Etsy does) and check that the output does not copy a protected work.","tags":["notion","printable","planner","pdf","screenshots","ai-disclosure"],"keywords":[],"factsThatChange":[{"fact":"Etsy AI-disclosure requirement. SNIPPET. Verify at https://www.etsy.com/legal/creativity/","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://www.etsy.com/legal/creativity/"]},{"fact":"Notion template-sharing features. UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.etsy.com/legal/creativity/"]}],"hardRules":[],"sources":[{"text":"- https://www.etsy.com/legal/creativity/ (platform policy: paraphrase, link only) - https://www.etsy.com/seller-handbook/article/1275449912004 (platform page: paraphrase, link only)","urls":["https://www.etsy.com/legal/creativity/","https://www.etsy.com/seller-handbook/article/1275449912004"],"licence":"platform policy: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"format-guides-ebooks","version":1,"category":"product-formats-pricing","title":"Guides and e-books: specific, short, current","body":"Sell narrow \"how to do X\" guides (10–40 pages) that are faster than piecing together free information. Lead with a table of contents and a free sample chapter. Date-stamp the content and say which jurisdiction it applies to, for example \"UK, checked October 2026\". Avoid get-rich-quick or income-claim framing: card networks and Stripe restrict it, and it risks misleading-advertising rules.\n\nGuides that are mainly AI-generated must still be accurate, original in structure and fact-checked. Low-value bulk e-books harm reputation and break marketplace rules. Health, legal and financial topics need extra care (see legal-no-regulated-advice).","tags":["ebook","guide","pdf","accuracy","income-claims"],"keywords":[],"factsThatChange":[{"fact":"Stripe's \"get rich quick\" prohibition. SNIPPET. Verify at https://stripe.com/legal/restricted-businesses","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/legal/restricted-businesses"]}],"hardRules":[],"sources":[{"text":"- https://stripe.com/legal/restricted-businesses (platform policy: paraphrase, link only)","urls":["https://stripe.com/legal/restricted-businesses"],"licence":"platform policy: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"format-micro-saas-tools","version":1,"category":"product-formats-pricing","title":"Small tools and micro-SaaS: higher value, higher obligations","body":"Small web tools, calculators, scripts and add-ons can sell as one-off licences or subscriptions. Before you build:\n- Confirm the channel allows software or \"AI services\". Gumroad prohibits \"AI services\" and \"Services\".\n- Plan for support, uptime and data protection. Any personal data you store makes you a UK GDPR controller.\n- Subscriptions bring extra duties: clear renewal terms and easy cancellation. The DMCC subscription regime is expected in spring 2027.\n\nStart with a one-off-price version, or a free tool with a paid upgrade. Never collect more data than the tool needs.","tags":["saas","software","tool","subscription","data-protection"],"keywords":[],"factsThatChange":[{"fact":"Gumroad prohibited list: VERIFIED at https://gumroad.com/prohibited","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://gumroad.com/prohibited","https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime"]},{"fact":"Subscription regime commencement, \"spring 2027\": SNIPPET from gov.uk. Verify at https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://gumroad.com/prohibited","https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime"]}],"hardRules":["Confirm the channel allows software or \"AI services\". Gumroad prohibits \"AI services\" and \"Services\"."],"sources":[{"text":"- https://gumroad.com/prohibited (platform page: paraphrase, link only) - gov.uk subscription consultation response, URL as above (OGL v3.0)","urls":["https://gumroad.com/prohibited","https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime"],"licence":"platform page: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"format-services-productised","version":1,"category":"product-formats-pricing","title":"Productised services (documentation, setup, audits)","body":"Package a service as a fixed scope, a fixed price and a fixed turnaround, for example \"Write your README and contributor guide: £79, 3 working days, 1 revision\". Write down exactly what is included and excluded.\n\nUnder UK distance-selling rules, consumers have a 14-day cancellation right for services. If they expressly ask you to start sooner and then cancel, they pay a proportionate amount for work already done.\n\nGumroad prohibits services. Use Stripe Payment Links, PayPal invoices or another channel that permits them. Never offer regulated services such as legal advice, financial advice or reserved legal activities.","tags":["service","done-for-you","documentation","scope","cancellation-services"],"keywords":[],"factsThatChange":[{"fact":"Gumroad \"Services\" prohibition. VERIFIED 2026-10-08.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/uksi/2013/3134"]},{"fact":"Services cancellation rules. Verify at https://www.legislation.gov.uk/uksi/2013/3134","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/uksi/2013/3134"]}],"hardRules":["Gumroad prohibits services. Use Stripe Payment Links, PayPal invoices or another channel that permits them. Never offer regulated services such as legal advice, financial advice or reserved legal activities."],"sources":[{"text":"- https://www.legislation.gov.uk/uksi/2013/3134 (legislation.gov.uk: OGL v3.0, Crown copyright. Paraphrase with attribution.) - https://gumroad.com/prohibited (platform page: link only)","urls":["https://www.legislation.gov.uk/uksi/2013/3134","https://gumroad.com/prohibited"],"licence":"legislation.gov.uk: OGL v3.0, Crown copyright. Paraphrase with attribution.","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"pricing-anchors-and-tiers","version":1,"category":"product-formats-pricing","title":"Price on value; use tiers and anchors honestly","body":"- Set the price from the buyer's value (time or money saved) and from competitor prices, not from your cost.\n- Typical ranges: small digital templates £3–£15, deeper toolkits £15–£49, productised services £50+.\n- Offer up to three tiers (basic, standard, plus bundle). The middle tier is usually the target.\n- Fixed per-sale fees (£0.20–£0.50) swamp very low prices. Check the net after fees (see econ-fee-impact) before you choose a price under £5.\n- Run sales and \"was\" prices only against a price you genuinely charged before. Fake reference prices and false urgency (\"only 2 left\" for a digital file) are misleading.","tags":["pricing","tiers","anchor","discount","was-price"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.asa.org.uk/advice-online/misleading-advertising.html (ASA/CAP: copyright ASA. Paraphrase, link only.) - CMA207 Unfair commercial practices guidance: https://assets.publishing.service.gov.uk/media/686666f2e4184a43f9785c0e/CMA207_Unfair_commercial_practices_guidance.pdf (OGL v3.0)","urls":["https://www.asa.org.uk/advice-online/misleading-advertising.html","https://assets.publishing.service.gov.uk/media/686666f2e4184a43f9785c0e/CMA207_Unfair_commercial_practices_guidance.pdf"],"licence":"ASA/CAP: copyright ASA. Paraphrase, link only.","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"pricing-bundles-upsells","version":1,"category":"product-formats-pricing","title":"Bundles, upsells and order bumps","body":"Bundles of related items (\"complete freelancer admin kit\") raise the average order value and do well on marketplaces. State exactly what is in a bundle and say if it overlaps products the buyer may already own. After a purchase, offer one relevant upgrade or complementary item, not a chain of offers. Never pre-tick paid add-ons: UK law requires the consumer's express consent to extra payments. Track the attach rate; if under about 5% of buyers take the upsell after 50 orders, change or drop it.","tags":["bundle","upsell","order-bump","pre-ticked","aov"],"keywords":[],"factsThatChange":[{"fact":"the ban on pre-ticked boxes (Consumer Contracts Regulations reg. 40). Verify at https://www.legislation.gov.uk/uksi/2013/3134/regulation/40","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/uksi/2013/3134/regulation/40"]}],"hardRules":[],"sources":[{"text":"legislation.gov.uk (OGL v3.0)","urls":["https://www.legislation.gov.uk/uksi/2013/3134/regulation/40"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"positioning-niche","version":1,"category":"product-formats-pricing","title":"Positioning: narrow audience, concrete promise","body":"Use this format: \"For [specific audience] who [specific situation], this [format] helps [outcome] in [time/effort].\" A narrow audience lowers competition, sharpens the copy and makes it obvious where to find customers. Every claim must be true and checkable; promised outcomes must be achievable for a typical buyer. Avoid \"guaranteed income\" or medical, financial or legal promises. Re-test positioning before changing the product: often the product is fine and the message is wrong.","tags":["positioning","audience","value-proposition","copywriting"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.asa.org.uk/advice-online/substantiation.html (ASA/CAP: paraphrase, link only)","urls":["https://www.asa.org.uk/advice-online/substantiation.html"],"licence":"ASA/CAP: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"policy-refunds","version":1,"category":"product-formats-pricing","title":"Write a clear, lawful refund policy","body":"Publish the refund policy before purchase.\n\nFor downloadable digital content, UK consumers lose the 14-day cancellation right once download starts, but only if both of these happened before supply:\n- they gave express consent to immediate supply\n- they acknowledged that they lose the right to cancel\n\nYou still owe Consumer Rights Act remedies: digital content must be of satisfactory quality, fit for purpose and as described. Faulty content means repair or replacement, then a price reduction or refund.\n\nA voluntary \"no-questions 14-day refund\" builds trust and reduces chargebacks. Decide per product whether you can afford it. Never say \"no refunds under any circumstances\", because statutory rights cannot be excluded.","tags":["refund","policy","statutory-rights","digital-content"],"keywords":[],"factsThatChange":[{"fact":"CCR regs 36–37 and the CRA 2015 digital content rules. Verify at https://www.legislation.gov.uk/uksi/2013/3134 and https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/uksi/2013/3134","https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3"]}],"hardRules":[],"sources":[{"text":"legislation.gov.uk (OGL v3.0); https://www.gov.uk/online-and-distance-selling-for-businesses (OGL v3.0)","urls":["https://www.gov.uk/online-and-distance-selling-for-businesses","https://www.legislation.gov.uk/uksi/2013/3134","https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"channel-gumroad","version":1,"category":"sales-channels","title":"Gumroad: merchant of record, simple, but restrictive on categories","body":"Good for downloadable products (templates, guides, printables, courses) sold through your own links.\n- Gumroad has been merchant of record since 1 January 2025. It handles sales tax and VAT worldwide, which removes the UK and EU VAT burden.\n- Fees are high, and sales from its Discover marketplace cost much more.\n- It prohibits \"Services\", \"Consulting firms\", \"AI services\", reselling private-label-rights products, \"Deceptive marketing practices\" and more. Read the prohibited list before you list.\n- Payouts are weekly, with holding periods and minimums. Budget for a cash-flow delay of a week or more.","tags":["gumroad","fees","merchant-of-record","prohibited","payout"],"keywords":[],"factsThatChange":[{"fact":"Direct sales fee 10% + $0.50; Discover sales 30%. VERIFIED on gumroad.com/pricing, which says processing is included.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]},{"fact":"A help snippet mentions 5% + $0.50 once monthly sales pass $20k, and an older snippet says card processing is extra. Conflicting: UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]},{"fact":"Merchant of record from 2025-01-01. VERIFIED.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]},{"fact":"Payout: weekly (Fridays), at least a 7-day hold. SNIPPET. Minimum $10 vs $100 conflicts between snippets: UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]},{"fact":"Prohibited list. VERIFIED.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]},{"fact":"KYC: identity and payout verification is required. Details UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"]}],"hardRules":["It prohibits \"Services\", \"Consulting firms\", \"AI services\", reselling private-label-rights products, \"Deceptive marketing practices\" and more. Read the prohibited list before you list."],"sources":[{"text":"the Gumroad pages above (platform pages: facts paraphrased, no copying, link only)","urls":["https://gumroad.com/pricing","https://gumroad.com/help/article/66-gumroads-fees","https://gumroad.com/help/article/13-getting-paid","https://gumroad.com/prohibited"],"licence":"platform pages: facts paraphrased, no copying, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-etsy-digital","version":1,"category":"sales-channels","title":"Etsy digital downloads: built-in traffic, strict originality rules","body":"Etsy brings buyers searching for printables, planners and templates.\n- Digital items must be designed by the seller (\"Designed by a seller\").\n- AI-assisted items made from your own prompts are allowed but must be disclosed in the listing. Selling AI prompt bundles is prohibited.\n- Etsy collects and remits VAT on automatically downloaded digital items for UK buyers (and others), so the UK below-threshold exemption does not help you there.\n- Fees stack up: listing, transaction, processing, a regulatory fee and possibly Offsite Ads. Model the net before pricing.\n- New UK sellers must verify their bank account. Funds are typically held for about 14 days at first, then deposited on a schedule (weekly on Monday by default).\n\n**Facts that change** (lastChecked 2026-10-08). The fee page returned HTTP 403, so all fees are SECONDARY unless marked:\n- Listing fee $0.20 per listing.\n- Transaction fee 6.5% of the order total.\n- UK Etsy Payments processing 4% + £0.20.\n- Regulatory operating fee for UK sellers: sources give 0.48% or 0.32%. UNVERIFIED.\n- Offsite Ads 12% or 15% of the attributed order, capped at $100.\n- Currency conversion 2.5%.\n- VAT charged on Etsy's own fees.\n- Payout (14-day new-seller hold, weekly default) and bank verification. SNIPPET from help.etsy.com.\n- Digital VAT collection. SNIPPET.\n- AI disclosure. SNIPPET.\n- Verify at https://www.etsy.com/legal/fees/, https://help.etsy.com/hc/en-gb/articles/115015587567, https://www.etsy.com/legal/creativity/ and https://help.etsy.com/hc/en-us/articles/360046998234","tags":["etsy","digital-download","fees","vat","ai-disclosure","payout"],"keywords":[],"factsThatChange":[],"hardRules":["AI-assisted items made from your own prompts are allowed but must be disclosed in the listing. Selling AI prompt bundles is prohibited."],"sources":[{"text":"the Etsy pages above (platform: paraphrase, link only)","urls":[],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-payhip","version":1,"category":"sales-channels","title":"Payhip: low fees, collects UK and EU VAT, paid straight to PayPal or Stripe","body":"A storefront for digital downloads, courses and memberships.\n- The free plan charges a percentage per sale; paid plans lower or remove it.\n- PayPal or Stripe processing fees apply on top.\n- Payhip says it collects and remits EU and UK VAT automatically. Confirm how it handles that legally before you depend on it.\n- Money goes directly to your connected PayPal or Stripe account. Stripe pays out daily by default, after an initial pending period for new accounts.\n- Allowed content follows Payhip's terms plus PayPal's and Stripe's restricted lists.","tags":["payhip","fees","vat","storefront"],"keywords":[],"factsThatChange":[{"fact":"Plans: Free $0/month with a 5% fee; Plus $29/month with 2%; Pro $99/month with 0%. VERIFIED on payhip.com/pricing.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://payhip.com/pricing","https://help.payhip.com/article/65-connecting-your-stripe-account"]},{"fact":"Processor fees extra. VERIFIED.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://payhip.com/pricing","https://help.payhip.com/article/65-connecting-your-stripe-account"]},{"fact":"UK and EU VAT collected and remitted. VERIFIED that Payhip claims this; whether it is legally the merchant of record is UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://payhip.com/pricing","https://help.payhip.com/article/65-connecting-your-stripe-account"]},{"fact":"Payout timing. SNIPPET from help.payhip.com.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://payhip.com/pricing","https://help.payhip.com/article/65-connecting-your-stripe-account"]}],"hardRules":[],"sources":[{"text":"Payhip pages (platform: paraphrase, link only)","urls":["https://payhip.com/pricing","https://help.payhip.com/article/65-connecting-your-stripe-account"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-lemon-squeezy","version":1,"category":"sales-channels","title":"Lemon Squeezy: merchant of record for software and digital products, now part of Stripe","body":"Lemon Squeezy is merchant of record and handles global sales tax and VAT. It suits software licences, SaaS subscriptions and digital products.\n- Fee is a percentage plus a fixed amount, with possible extra fees on international sales.\n- Payouts go out twice monthly, after a 13-day hold and above a minimum.\n- Stores need approval or activation, so expect review of your product and identity.\n- Stripe has owned it since 2024. Since 2026 Stripe has offered \"Stripe Managed Payments\", a merchant-of-record option at the same headline price that works with Stripe Checkout and Payment Links. Compare both before committing; migration risk is real.","tags":["lemon-squeezy","stripe-managed-payments","merchant-of-record","saas","payout"],"keywords":[],"factsThatChange":[{"fact":"Fee 5% + 50¢; \"small additional fees\" on international sales; no monthly fee; merchant of record. VERIFIED on lemonsqueezy.com/pricing.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.lemonsqueezy.com/pricing","https://docs.lemonsqueezy.com/help/getting-started/getting-paid","https://docs.stripe.com"]},{"fact":"Payouts on the 14th and 28th after a 13-day hold; $50 minimum. SNIPPET from docs.lemonsqueezy.com.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://www.lemonsqueezy.com/pricing","https://docs.lemonsqueezy.com/help/getting-started/getting-paid","https://docs.stripe.com"]},{"fact":"Stripe Managed Payments details (5% + $0.50, Checkout and Payment Links only). SECONDARY.","lastChecked":"2026-10-08","confidence":"secondary","staleAfterDays":90,"verifyAt":["https://www.lemonsqueezy.com/pricing","https://docs.lemonsqueezy.com/help/getting-started/getting-paid","https://docs.stripe.com"]},{"fact":"KYC and store activation requirements. UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.lemonsqueezy.com/pricing","https://docs.lemonsqueezy.com/help/getting-started/getting-paid","https://docs.stripe.com"]}],"hardRules":[],"sources":[{"text":"Lemon Squeezy and Stripe pages (platform: paraphrase, link only)","urls":["https://www.lemonsqueezy.com/pricing","https://docs.lemonsqueezy.com/help/getting-started/getting-paid","https://docs.stripe.com"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-ko-fi","version":1,"category":"sales-channels","title":"Ko-fi: creator shop and tips; payments go directly to you","body":"Ko-fi suits creator-style audiences (tips, small shop items, memberships, commissions).\n- It never holds funds: payments go directly to your PayPal or Stripe account, and their fees apply.\n- The free plan charges a service fee on shop, membership and commission sales.\n- Ko-fi Gold (a monthly subscription) removes platform fees. It is worth it only when monthly sales are high enough; work out the break-even point.\n- Ko-fi is not a merchant of record, so VAT and consumer-law duties stay with the seller.\n\n**Facts that change** (lastChecked 2026-10-08). Pricing page returned HTTP 403:\n- 5% fee on shop, membership and commission sales on the free plan. SNIPPET and SECONDARY.\n- Tips: 0% on the free plan per some sources. Conflicting: UNVERIFIED.\n- Gold price: $12/month in recent sources ($6–8 historically). UNVERIFIED.\n- Verify at https://help.ko-fi.com/hc/en-us/articles/360002506494-Does-Ko-fi-take-a-fee and https://ko-fi.com/gold","tags":["ko-fi","creator","tips","membership","gold"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"Ko-fi help (platform: paraphrase, link only)","urls":[],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-paypal-links-invoicing","version":1,"category":"sales-channels","title":"PayPal payment links and invoices (UK business account)","body":"Useful for productised services and direct sales to buyers who prefer PayPal.\n- Commercial transactions on a UK business account cost a percentage plus a fixed fee per currency. Cross-border payments add a surcharge.\n- Invoices are charged at commercial rates.\n- PayPal is not a merchant of record: VAT, consumer law and your own terms are the seller's job.\n- Get a business account in the operator-approved legal identity. Expect KYC and possible holds or reserves on new or high-risk accounts.\n- PayPal's Acceptable Use Policy applies.","tags":["paypal","invoice","payment-link","fees","cross-border"],"keywords":[],"factsThatChange":[{"fact":"2.9% + £0.30 domestic.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"]},{"fact":"+1.29% for EEA payments, +1.99% for other markets.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"]},{"fact":"Tiered rates as low as 2.1% above £8,000 a month, on request.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"]},{"fact":"All the above VERIFIED on paypal.com/uk (page \"last updated 1 October 2026\").","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"]},{"fact":"Holds and reserves: UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"]}],"hardRules":[],"sources":[{"text":"PayPal UK pages (platform: paraphrase, link only)","urls":["https://www.paypal.com/uk/webapps/mpp/merchant-fees","https://www.paypal.com/uk/legalhub/acceptableuse-full"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-stripe-payment-links","version":1,"category":"sales-channels","title":"Stripe Payment Links: cheapest processing, seller does all compliance","body":"No-code checkout links for one-off or recurring payments. Processing costs are lowest for UK cards.\n- Stripe is not merchant of record unless you use Managed Payments. With plain links, UK VAT, EU VAT (no threshold for UK sellers), consumer terms and refunds are all on you.\n- Activation requires business and identity KYC.\n- The first payout usually comes about 7 days after the first payment, longer in some industries. Later UK payouts follow your schedule.\n- Read the Prohibited and Restricted Businesses list. \"Get rich quick\" offers and misleading claims are prohibited.","tags":["stripe","payment-link","fees","kyc","restricted-businesses"],"keywords":[],"factsThatChange":[{"fact":"UK standard cards 1.5% + 20p; premium UK cards 2.8% + 20p.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]},{"fact":"EEA cards 2.5% + 20p; non-EEA cards 3.15% + 20p as read today. Earlier public figures said 3.25%, so re-verify.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]},{"fact":"+2% currency conversion.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]},{"fact":"No extra fee for Payment Links; custom domain £10/month.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]},{"fact":"All the above VERIFIED on stripe.com/gb/pricing.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]},{"fact":"First payout about 7 days. SNIPPET.","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"]}],"hardRules":["Read the Prohibited and Restricted Businesses list. \"Get rich quick\" offers and misleading claims are prohibited."],"sources":[{"text":"Stripe pages (platform: paraphrase, link only)","urls":["https://stripe.com/gb/pricing","https://support.stripe.com/questions/waiting-period-for-first-payout-on-stripe","https://stripe.com/legal/restricted-businesses"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"channel-choose","version":1,"category":"sales-channels","title":"Choosing a channel: a decision checklist","body":"Choose by product type and who carries compliance.\n\n| Product | Channel |\n|---|---|\n| Downloadable product, buyers worldwide | A merchant of record (Gumroad, Lemon Squeezy or Stripe Managed Payments) or Etsy, which handle VAT |\n| Discovery needed | Etsy (search traffic), or Gumroad Discover at a 30% fee |\n| Services | Stripe or PayPal links (Gumroad prohibits services) |\n| Creator audience | Ko-fi or Payhip |\n\nCheck four things in this order:\n1. Is the item permitted?\n2. Who handles VAT and consumer obligations?\n3. What is the net margin after fees at your price?\n4. How long until cash arrives (payout hold and schedule)?\n\nDo not open more than one account on the same platform, and never open a new one to get around a suspension or ban (platforms treat it as ban evasion). Open accounts only where you will actually sell; every account you open is logged in your footprint and the owner can freeze it.","tags":["channel-selection","decision","comparison"],"keywords":[],"factsThatChange":[{"fact":"see the individual channel entries.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":["| Services | Stripe or PayPal links (Gumroad prohibits services) |","Do not open more than one account on the same platform, and never open a new one to get around a suspension or ban (platforms treat it as ban evasion). Open accounts only where you will actually sell; every account you open is logged in your footprint and the owner can freeze it."],"sources":[{"text":"as per the channel entries.","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"acq-seo-basics","version":1,"category":"acquisition","title":"SEO basics for product and content pages","body":"- One page per clear search intent. Use the buyer's words in the title, the H1 and the first paragraph.\n- Write descriptive, honest product copy and add an FAQ that answers real questions.\n- Use fast pages, descriptive image alt text and internal links.\n- Earn links with genuinely useful free resources.\n\nDo not mass-produce thin or AI-spun pages. Google's spam policies name \"scaled content abuse\" (many low-value pages, AI-generated or not, made to manipulate rankings) and can de-rank or remove a site. Quality and originality beat volume. Measure impressions and clicks in Search Console.","tags":["seo","google","spam-policy","scaled-content"],"keywords":[],"factsThatChange":[{"fact":"Google spam policies, updated periodically (e.g. the site reputation policy in August 2026). Verify at https://developers.google.com/search/docs/essentials/spam-policies","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://developers.google.com/search/docs/essentials/spam-policies"]}],"hardRules":["Do not mass-produce thin or AI-spun pages. Google's spam policies name \"scaled content abuse\" (many low-value pages, AI-generated or not, made to manipulate rankings) and can de-rank or remove a site. Quality and originality beat volume. Measure impressions and clicks in Search Console."],"sources":[{"text":"- Google Search Central (content generally CC BY 4.0, code Apache 2.0. Paraphrase with attribution.) - https://developers.google.com/search/docs/fundamentals/using-gen-ai-content","urls":["https://developers.google.com/search/docs/fundamentals/using-gen-ai-content","https://developers.google.com/search/docs/essentials/spam-policies"],"licence":"content generally CC BY 4.0, code Apache 2.0. Paraphrase with attribution.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"acq-content-marketing","version":1,"category":"acquisition","title":"Content marketing: give away the \"what\", sell the \"done-for-you\"","body":"Publish free, genuinely useful material (short guides, checklists, worked examples) on the problem your product solves, then link to the product as the faster option. Each piece targets one question your audience asks. Repurpose one core piece into several formats (article, thread, short video script) by hand-adapting it, not by posting duplicates. Track which pieces lead to email sign-ups or sales; stop producing types that convert nothing after about 10 attempts. Label sponsored or affiliate content clearly.","tags":["content","blog","repurpose","funnel"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.asa.org.uk/advice-online/recognising-ads-brand-owned-and-paid-social-media.html (ASA/CAP: paraphrase, link only)","urls":["https://www.asa.org.uk/advice-online/recognising-ads-brand-owned-and-paid-social-media.html"],"licence":"ASA/CAP: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"acq-communities-reddit","version":1,"category":"acquisition","title":"Communities and Reddit: participate first, promote rarely","body":"Reddit's own guidance is roughly \"fine to be a Redditor with a website, not a website with a Reddit account\". Its long-standing heuristic is that most of your activity (often given as 9:1) should not be self-promotion.\n- Each subreddit has its own rules and many ban self-promotion completely. Read the sidebar and rules before posting.\n- Disclose that you made the product. Never use multiple accounts, vote manipulation or undisclosed shilling.\n- Agents posting on community platforms must follow the platform's rules on automated or bot accounts and must not pretend to be a human customer.\n- Prefer answering questions helpfully; link only when it directly answers the question and the rules allow it.","tags":["reddit","community","self-promotion","disclosure"],"keywords":[],"factsThatChange":[{"fact":"Reddit's spam and self-promotion guidance and API/bot rules. UNVERIFIED: reddit.com could not be fetched; the content came via secondary sources. Verify at https://support.reddithelp.com (search \"spam\" and \"self-promotion\") and https://redditinc.com/policies","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://support.reddithelp.com","https://redditinc.com/policies"]}],"hardRules":[],"sources":[{"text":"Reddit help and policies (platform: paraphrase, link only)","urls":["https://support.reddithelp.com","https://redditinc.com/policies"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"acq-email-pecr-gdpr","version":1,"category":"acquisition","title":"Email lists in the UK: consent (PECR) and UK GDPR","body":"- You may not send marketing email to individuals without their specific consent. The exception is the \"soft opt-in\": an existing customer who bought, or negotiated to buy, from you and was offered a clear opt-out when you collected their details. Marketing to them must be about your similar products, with an opt-out in every message.\n- Never buy, rent or scrape lists.\n- Identify yourself, give a valid contact or unsubscribe address, and act on opt-outs promptly.\n- Keep consent records (when, where, what wording).\n- Use double opt-in and a privacy notice.\n\nThe ICO notes this guidance is under review because of the Data (Use and Access) Act 2025.","tags":["email","newsletter","pecr","soft-opt-in","consent"],"keywords":[],"factsThatChange":[{"fact":"The rules in the guidance: VERIFIED on the ICO page, which notes it is \"under review\".","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/guide-to-pecr/electronic-and-telephone-marketing/electronic-mail-marketing/"]},{"fact":"DUAA 2025 changes, including higher PECR fines: UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/guide-to-pecr/electronic-and-telephone-marketing/electronic-mail-marketing/"]}],"hardRules":["Never buy, rent or scrape lists."],"sources":[{"text":"ICO (most ICO content is OGL v3.0. Paraphrase with attribution.)","urls":["https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/guide-to-pecr/electronic-and-telephone-marketing/electronic-mail-marketing/"],"licence":"most ICO content is OGL v3.0. Paraphrase with attribution.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"acq-social-automation-rules","version":1,"category":"acquisition","title":"Social platforms: automation and spam rules","body":"- Automated posting is allowed on some platforms only within their rules.\n- X's automation rules forbid spam; automated posting about trending topics to manipulate them; duplicate or near-duplicate posts across one or several accounts; and automated unsolicited mentions, replies or DMs.\n- Authenticity rules ban fake or mass-registered accounts and artificial amplification.\n- If an account is automated, use the platform's bot or automated-account label where one exists.\n\nOne account per agent identity, approved by the operator. Write posts for humans. Never automate engagement (likes, follows, replies) to inflate reach.","tags":["social","x-twitter","automation","bot","spam"],"keywords":[],"factsThatChange":[{"fact":"X automation and authenticity policies. SNIPPET. Verify at https://help.x.com/en/rules-and-policies/x-automation and https://help.x.com/en/rules-and-policies/authenticity. Check each other platform's equivalent (Meta, LinkedIn, TikTok, Pinterest): UNVERIFIED.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://help.x.com/en/rules-and-policies/x-automation","https://help.x.com/en/rules-and-policies/authenticity"]}],"hardRules":[],"sources":[{"text":"X Help Center (platform: paraphrase, link only)","urls":["https://help.x.com/en/rules-and-policies/x-automation","https://help.x.com/en/rules-and-policies/authenticity"],"licence":"platform: paraphrase, link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"acq-marketplace-listing-optimisation","version":1,"category":"acquisition","title":"Marketplace listing quality","body":"- Title: buyer's search phrase plus format plus audience.\n- First image: shows the actual product clearly.\n- Description: the problem it solves, exactly what is included, compatibility, how delivery works, the refund terms, and an AI-use disclosure where required.\n- Use all available tags with real search phrases.\n\nPrice within the observed range unless you have a clear differentiator. Answer questions fast and respond professionally to reviews. Never ask for \"5-star only\" reviews or offer incentives for positive ones.","tags":["listing","tags","title","images","marketplace-seo"],"keywords":[],"factsThatChange":[{"fact":"Etsy listing and AI-disclosure rules. SNIPPET. Verify at https://www.etsy.com/legal/creativity/","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://www.etsy.com/legal/creativity/"]}],"hardRules":[],"sources":[{"text":"Etsy policy (link only); CMA208 (OGL v3.0)","urls":["https://www.etsy.com/legal/creativity/"],"licence":"OGL v3.0","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"delivery-digital-goods","version":1,"category":"delivery-support","title":"Reliable delivery of digital goods","body":"Use automatic delivery through the platform: an instant download or an emailed link. It is reliable and counts as an \"electronically supplied service\" for VAT (manually emailed PDFs are treated differently).\n- Test the full purchase-to-download flow on a fresh account before launch and after every file change.\n- Version your files and keep a changelog.\n- Confirm in the checkout flow that the buyer gave the immediate-supply consent and acknowledgement (see legal-digital-content-cancellation).\n- Make sure links don't expire too fast, and offer re-sends.\n- Keep the files in your own store too, not only on the platform.","tags":["delivery","download","file-versioning","esss"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers (OGL v3.0)","urls":["https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"support-customer-service","version":1,"category":"delivery-support","title":"Customer support: fast, human-quality, honest","body":"- Publish a support contact and a response-time target (e.g. one working day).\n- Use templates for common issues (can't download, wrong format, how to edit) but personalise every reply.\n- Resolve quickly: re-send, fix, give a partial refund or a full refund.\n- Log every ticket and look for patterns; fix the product or description that causes repeat questions.\n- UK law requires your identity and geographic address in pre-contract information.\n- If a customer sincerely asks whether they're talking to an AI, say truthfully that you are (see ethics-ai-disclosure).\n- Escalate threats, legal claims and data-subject requests to the operator.","tags":["support","tickets","response-time","escalation"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"- https://www.legislation.gov.uk/uksi/2013/3134/schedule/2 (OGL v3.0)","urls":["https://www.legislation.gov.uk/uksi/2013/3134/schedule/2"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"support-chargebacks","version":1,"category":"delivery-support","title":"Avoiding and handling chargebacks","body":"Chargebacks cost a fee plus the sale amount, and they hurt account standing. Prevent them:\n- Use a recognisable billing descriptor.\n- Describe the product accurately.\n- Deliver instantly.\n- Keep the consent-to-immediate-supply evidence.\n- Refund promptly when someone asks; a refund is cheaper than a dispute.\n\nIf a dispute arrives, respond within the processor's deadline with evidence: product description, delivery and download logs, consent record and communications. A high dispute rate can freeze accounts. Merchant-of-record platforms handle disputes but may pass on fees.","tags":["chargeback","dispute","evidence","fraud"],"keywords":[],"factsThatChange":[{"fact":"chargeback fees and deadlines per processor. UNVERIFIED. Verify at https://stripe.com/gb/pricing and https://www.paypal.com/uk/webapps/mpp/merchant-fees","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://stripe.com/gb/pricing","https://www.paypal.com/uk/webapps/mpp/merchant-fees"]}],"hardRules":[],"sources":[{"text":"Stripe and PayPal pages (link only)","urls":["https://stripe.com/gb/pricing","https://www.paypal.com/uk/webapps/mpp/merchant-fees"],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"legal-digital-content-cancellation","version":1,"category":"uk-legal-compliance","title":"14-day cancellation and the digital-content waiver (CCR 2013)","body":"Distance contracts generally carry a 14-day cancellation right. For digital content not on a tangible medium, the right ends once supply begins, but only if, before supply:\n1. the consumer gave express consent to supply starting within the cancellation period, and\n2. acknowledged they will lose the right to cancel, and\n3. you confirm this on a durable medium (e.g. the confirmation email).\n\nImplement this as an unticked checkbox at checkout plus wording in the receipt. Without it, the buyer can cancel within 14 days even after downloading. Services follow different rules (see format-services-productised).","tags":["ccr-2013","cancellation","14-day","waiver","checkbox"],"keywords":[],"factsThatChange":[{"fact":"CCR regs 36–37. Verify at https://www.legislation.gov.uk/uksi/2013/3134 and https://www.gov.uk/online-and-distance-selling-for-businesses","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/uksi/2013/3134","https://www.gov.uk/online-and-distance-selling-for-businesses"]}],"hardRules":[],"sources":[{"text":"legislation.gov.uk and gov.uk (OGL v3.0. Paraphrase with attribution.)","urls":["https://www.legislation.gov.uk/uksi/2013/3134","https://www.gov.uk/online-and-distance-selling-for-businesses"],"licence":"OGL v3.0. Paraphrase with attribution.","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-consumer-rights-digital","version":1,"category":"uk-legal-compliance","title":"Consumer Rights Act 2015: quality of digital content","body":"Digital content sold to UK consumers must be of satisfactory quality, fit for any purpose made known, and as described. What you say in listings becomes part of the contract. If the content is faulty, the consumer is entitled to repair or replacement, then a price reduction or refund, and to compensation if your content damages their device or other content through lack of reasonable care. These rights cannot be excluded by your terms. Describe compatibility and limitations honestly to avoid disputes.","tags":["cra-2015","quality","remedies","digital-content"],"keywords":[],"factsThatChange":[{"fact":"CRA 2015 Part 1, Chapter 3. Verify at https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3"]}],"hardRules":[],"sources":[{"text":"legislation.gov.uk (OGL v3.0)","urls":["https://www.legislation.gov.uk/ukpga/2015/15/part/1/chapter/3"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-trader-information","version":1,"category":"uk-legal-compliance","title":"Mandatory seller information and terms","body":"Before purchase, give consumers:\n- your identity (trading name)\n- a geographic address and contact details\n- the main characteristics of the product\n- the total price including taxes\n- payment and delivery arrangements\n- cancellation rights or their loss\n- digital-content functionality and compatibility\n\nOnline, the E-Commerce Regulations 2002 also require trader identity and contact details to be easily accessible. Publish terms, a refund policy and a privacy notice. Agents use the operator-approved legal identity and address, never invented ones.","tags":["trader-info","address","terms","e-commerce-regs"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"legislation.gov.uk (OGL v3.0)","urls":["https://www.legislation.gov.uk/uksi/2013/3134/schedule/2","https://www.legislation.gov.uk/uksi/2002/2013"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-vat-digital","version":1,"category":"uk-legal-compliance","title":"VAT on digital products: UK and EU","body":"- **UK:** you must register for VAT when taxable turnover goes over £90,000 in any 12 months, or is expected to within the next 30 days.\n- **Electronically supplied services** (automatically delivered: e-books, software, templates by auto-download) to consumers are taxed where the consumer lives.\n- **EU consumers:** a UK seller has no EU threshold. You must register for the non-Union OSS scheme in one EU member state, or register in each country where you sell.\n- **Platforms:** when a platform controls the charge, delivery or terms, it is usually treated as the supplier for VAT. Merchant-of-record platforms (Gumroad, Lemon Squeezy, Stripe Managed Payments) and Etsy collect the VAT.\n\nRecommendation: route sales to EU consumers through a merchant of record or marketplace. Get tax decisions approved by the operator.","tags":["vat","oss","eu-vat","threshold","marketplace-deemed-supplier"],"keywords":[],"factsThatChange":[{"fact":"£90,000 threshold (since 1 April 2024). VERIFIED (gov.uk snippet).","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.gov.uk/register-for-vat","https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers","https://vat-one-stop-shop.ec.europa.eu"]},{"fact":"Digital-services guidance (page last updated 28 March 2022). VERIFIED.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.gov.uk/register-for-vat","https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers","https://vat-one-stop-shop.ec.europa.eu"]},{"fact":"EU non-Union OSS. Verify on the EU side as well.","lastChecked":"2026-10-08","confidence":"verified-official","staleAfterDays":90,"verifyAt":["https://www.gov.uk/register-for-vat","https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers","https://vat-one-stop-shop.ec.europa.eu"]}],"hardRules":["**UK:** you must register for VAT when taxable turnover goes over £90,000 in any 12 months, or is expected to within the next 30 days.","**EU consumers:** a UK seller has no EU threshold. You must register for the non-Union OSS scheme in one EU member state, or register in each country where you sell."],"sources":[{"text":"gov.uk (OGL v3.0); EU OSS portal","urls":["https://www.gov.uk/register-for-vat","https://www.gov.uk/guidance/the-vat-rules-if-you-supply-digital-services-to-private-consumers","https://vat-one-stop-shop.ec.europa.eu"],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-income-tax-registration","version":1,"category":"uk-legal-compliance","title":"Income tax and HMRC registration basics","body":"Trading income generally needs reporting to HMRC.\n- The £1,000 trading allowance covers small gross trading income.\n- Above it, register for Self Assessment, or account through a company if the operator runs one.\n- Keep records of every sale, fee, refund and expense from day one. Platform reports (Etsy and others report UK sellers' income to HMRC under the digital platform reporting rules) will be cross-checked.\n\nThe legal entity and tax status are operator decisions. Agents record the data and never make filings themselves.","tags":["hmrc","self-assessment","trading-allowance","platform-reporting"],"keywords":[],"factsThatChange":[{"fact":"trading allowance and platform reporting rules. UNVERIFIED in this session. Verify at https://www.gov.uk/guidance/tax-free-allowances-on-property-and-trading-income and https://www.gov.uk/guidance/reporting-rules-for-digital-platforms. Etsy's reporting page: https://help.etsy.com/hc/en-us/articles/17795509361431","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.gov.uk/guidance/tax-free-allowances-on-property-and-trading-income","https://www.gov.uk/guidance/reporting-rules-for-digital-platforms","https://help.etsy.com/hc/en-us/articles/17795509361431"]}],"hardRules":[],"sources":[{"text":"gov.uk (OGL v3.0); Etsy (link only)","urls":["https://www.gov.uk/guidance/tax-free-allowances-on-property-and-trading-income","https://www.gov.uk/guidance/reporting-rules-for-digital-platforms","https://help.etsy.com/hc/en-us/articles/17795509361431"],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"legal-uk-gdpr-basics","version":1,"category":"uk-legal-compliance","title":"UK GDPR basics for customer data","body":"You are a data controller for customer names, emails and payment metadata you hold.\n- Collect only what you need and have a lawful basis: contract for fulfilment; consent or soft opt-in for marketing.\n- Publish a privacy notice: who you are, what you collect, why, how long you keep it, and people's rights.\n- Keep data secure; use processors under proper terms (platforms, email tools).\n- Answer access or deletion requests within one month (escalate them to the operator).\n- Report serious breaches to the ICO within 72 hours.\n- Most organisations that process personal data must pay the ICO data protection fee (tier 1, micro organisations, is £52) unless exempt. Use the ICO self-assessment.","tags":["uk-gdpr","privacy-notice","ico-fee","dsar","breach"],"keywords":[],"factsThatChange":[{"fact":"fee tiers (£52, £78, £3,763 from 2025). SNIPPET from ico.org.uk and gov.uk. Verify at https://ico.org.uk/for-organisations/data-protection-fee/ and https://ico.org.uk/for-organisations/advice-for-small-organisations/","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://ico.org.uk/for-organisations/data-protection-fee/","https://ico.org.uk/for-organisations/advice-for-small-organisations/"]}],"hardRules":[],"sources":[{"text":"ICO (OGL v3.0); legislation.gov.uk SI 2025/63 (OGL)","urls":["https://ico.org.uk/for-organisations/data-protection-fee/","https://ico.org.uk/for-organisations/advice-for-small-organisations/"],"licence":"OGL","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-advertising-cap-code","version":1,"category":"uk-legal-compliance","title":"Advertising standards: the CAP Code basics","body":"The CAP Code covers non-broadcast marketing, including your own website and social posts.\n- Marketing must not mislead, including by leaving things out or by exaggerating.\n- Before publishing an objective claim (\"saves 5 hours a week\", \"best-selling\"), you must hold evidence for it.\n- Ads must be obviously identifiable as ads; label affiliate, sponsored and incentivised content.\n- Price claims (sales, \"was\" prices, \"free\") must be genuine.\n- Testimonials must be real and you need permission to use them.\n\nThe ASA can rule against you publicly, and platforms may act on rulings.","tags":["cap-code","asa","substantiation","ad-labelling"],"keywords":[],"factsThatChange":[{"fact":"CAP Code updates. Verify at https://www.asa.org.uk/codes-and-rulings/advertising-codes/non-broadcast-code.html","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.asa.org.uk/codes-and-rulings/advertising-codes/non-broadcast-code.html"]}],"hardRules":["Before publishing an objective claim (\"saves 5 hours a week\", \"best-selling\"), you must hold evidence for it."],"sources":[{"text":"ASA/CAP (copyright ASA/CAP: paraphrase only, link only, no reproduction of code text)","urls":["https://www.asa.org.uk/codes-and-rulings/advertising-codes/non-broadcast-code.html"],"licence":"copyright ASA/CAP: paraphrase only, link only, no reproduction of code text","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"legal-no-regulated-advice","version":1,"category":"uk-legal-compliance","title":"Don't give regulated advice","body":"Do not sell personalised legal, financial or investment, tax, medical or mental-health advice.\n- Investment and financial content may also be a financial promotion under FSMA s.21 and needs FCA authorisation or approval.\n- Some legal activities are reserved under the Legal Services Act 2007.\n- Medical claims carry ASA, CAP and MHRA risk.\n\nSafe pattern: general educational information plus tools (trackers, templates, checklists), clearly labelled \"general information, not advice\". Link to official sources (gov.uk, NHS, MoneyHelper) and point buyers to a qualified professional. Never promise financial outcomes.","tags":["regulated-advice","fca","financial-promotion","medical","legal-services"],"keywords":[],"factsThatChange":[{"fact":"FCA financial promotion rules. UNVERIFIED this session. Verify at https://www.fca.org.uk/firms/financial-promotions-adverts and https://www.legislation.gov.uk/ukpga/2007/29/part/3","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.fca.org.uk/firms/financial-promotions-adverts","https://www.legislation.gov.uk/ukpga/2007/29/part/3"]}],"hardRules":["Do not sell personalised legal, financial or investment, tax, medical or mental-health advice."],"sources":[{"text":"FCA (FCA website terms: paraphrase, link only); legislation.gov.uk (OGL)","urls":["https://www.fca.org.uk/firms/financial-promotions-adverts","https://www.legislation.gov.uk/ukpga/2007/29/part/3"],"licence":"OGL","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"legal-ip-copyright-trademark","version":1,"category":"uk-legal-compliance","title":"Copyright, trademarks and AI-generated content","body":"- Sell only material you created or have a licence to sell commercially. Check licence terms for fonts, images, icons and templates.\n- Don't use brand names or logos in ways that suggest endorsement (e.g. \"Official Notion template\", Disney characters). Describing compatibility, such as \"for Notion\", is usually acceptable when done factually.\n- Gumroad prohibits reselling private-label-rights products and copyrighted media. Etsy requires digital items to be designed by the seller.\n- AI output can reproduce protected material, so review it for similarity.\n- Under UK law, the protection for wholly computer-generated works (CDPA s.9(3)) is proposed for removal. Assume pure AI output may have weak or no copyright protection, and add real human creative contribution.\n- Respond to takedown notices promptly; escalate to the operator.","tags":["copyright","trademark","licence","plr","ai-copyright"],"keywords":[],"factsThatChange":[{"fact":"UK AI copyright policy (government report 2026; s.9(3) removal proposed). SNIPPET. Verify at https://www.gov.uk/government/publications/report-and-impact-assessment-on-copyright-and-artificial-intelligence and https://www.gov.uk/government/consultations/copyright-and-artificial-intelligence","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://www.gov.uk/government/publications/report-and-impact-assessment-on-copyright-and-artificial-intelligence","https://www.gov.uk/government/consultations/copyright-and-artificial-intelligence"]}],"hardRules":["Don't use brand names or logos in ways that suggest endorsement (e.g. \"Official Notion template\", Disney characters). Describing compatibility, such as \"for Notion\", is usually acceptable when done factually.","Gumroad prohibits reselling private-label-rights products and copyrighted media. Etsy requires digital items to be designed by the seller."],"sources":[{"text":"gov.uk (OGL v3.0); Gumroad and Etsy policies (link only)","urls":["https://www.gov.uk/government/publications/report-and-impact-assessment-on-copyright-and-artificial-intelligence","https://www.gov.uk/government/consultations/copyright-and-artificial-intelligence"],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"legal-reviews-dmcc","version":1,"category":"uk-legal-compliance","title":"Reviews law (DMCC Act 2024)","body":"Since April 2025 these are banned practices, automatically unfair:\n- writing, commissioning or offering fake reviews\n- publishing incentivised reviews without clearly saying so\n- presenting reviews misleadingly, e.g. hiding negative ones or showing distorted star averages\n\nIf you publish reviews, you must take reasonable steps to prevent fake and concealed-incentive reviews. The CMA can now fine directly, up to 10% of global turnover. Asking real customers for honest reviews is fine; tying a reward to a positive review is not.","tags":["reviews","dmcc","fake-reviews","cma","incentives"],"keywords":[],"factsThatChange":[{"fact":"CMA208 guidance (4 April 2025). SNIPPET from gov.uk. Verify at https://assets.publishing.service.gov.uk/media/67eeb64fe9c76fa33048c790/CMA208_-_Fake_reviews_guidance.pdf","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://assets.publishing.service.gov.uk/media/67eeb64fe9c76fa33048c790/CMA208_-_Fake_reviews_guidance.pdf"]}],"hardRules":["Since April 2025 these are banned practices, automatically unfair: writing, commissioning or offering fake reviews; publishing incentivised reviews without clearly saying so; presenting reviews misleadingly, e.g. hiding negative ones or showing distorted star averages","If you publish reviews, you must take reasonable steps to prevent fake and concealed-incentive reviews. The CMA can now fine directly, up to 10% of global turnover. Asking real customers for honest reviews is fine; tying a reward to a positive review is not."],"sources":[{"text":"CMA and gov.uk (OGL v3.0)","urls":["https://assets.publishing.service.gov.uk/media/67eeb64fe9c76fa33048c790/CMA208_-_Fake_reviews_guidance.pdf"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"legal-subscriptions","version":1,"category":"uk-legal-compliance","title":"Subscriptions and auto-renewals","body":"If you sell subscriptions:\n- State the price, billing frequency, renewal terms and how to cancel before purchase.\n- Make cancellation as easy as signing up.\n- Send renewal reminders.\n\nThe DMCC Act's subscription regime (pre-contract information, reminder notices, cooling-off notices, easy exit) is expected to start in spring 2027. Build to it now, because it is already good practice and it avoids \"subscription trap\" findings under unfair-practices rules.","tags":["subscription","auto-renewal","dmcc","cancellation"],"keywords":[],"factsThatChange":[{"fact":"start date \"spring 2027\". SNIPPET from gov.uk (government response of 2 April 2026). Verify at https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime","lastChecked":"2026-10-08","confidence":"official-snippet","staleAfterDays":90,"verifyAt":["https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime"]}],"hardRules":[],"sources":[{"text":"gov.uk (OGL v3.0)","urls":["https://www.gov.uk/government/consultations/consultation-on-the-implementation-of-the-new-subscription-contracts-regime"],"licence":"OGL v3.0","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"econ-fee-impact","version":1,"category":"unit-economics","title":"Calculate net per sale before choosing price and channel","body":"Net = price − VAT (if the platform deducts it) − platform % − fixed fee − processing − currency conversion − expected refunds. The fixed fee dominates at low prices.\n\nWorked examples on a £5 sale:\n- Gumroad direct (10% + $0.50, about £0.37): about £4.13 net, or 17% in fees.\n- Stripe link, UK card: £5 − (1.5% + 20p) = £4.73, but you handle VAT yourself.\n- Etsy (listing $0.20 + 6.5% + 4% + £0.20 + regulatory fee): about £4.13 or less, before Offsite Ads and VAT.\n\nIf fees are over 20% of price, raise the price, bundle items, or change channel.","tags":["fees","net-margin","unit-economics","calculator"],"keywords":[],"factsThatChange":[{"fact":"all fee rates. See the channel entries; re-verify before calculating. FX rates vary.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":[],"sources":[{"text":"see the channel entries.","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"econ-experiment-budget-runway","version":1,"category":"unit-economics","title":"Runway and cost per experiment","body":"- Runway = available protected cash ÷ monthly burn (compute, subscriptions, platform plans, domain).\n- Fix a cost cap per experiment (money and agent-hours). Never run more experiments in parallel than runway allows if all of them fail.\n- Prefer zero-fixed-cost channels until there are sales, i.e. pay-per-sale over monthly plans. Upgrade to a paid plan only when its break-even is met consistently. Examples: Payhip Plus at $29/month beats the free plan above about $1,000/month in sales; Ko-fi Gold beats the free plan when monthly sales exceed 20× its monthly fee.\n- Capital requests go through the controller; agents never approve their own.","tags":["runway","burn","budget","capital-request"],"keywords":[],"factsThatChange":[{"fact":"plan prices. See the channel entries.","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":[],"sources":[{"text":"internal (fleet economic policy: sweeps are on net profit, protected capital as defined in the charter).","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"econ-stop-rules","version":1,"category":"unit-economics","title":"When to stop, pivot or double down","body":"Decide the rules before launch.\n- **Stop:** zero sales after a fair exposure, e.g. 500+ targeted visitors or 30 days live with active promotion, and no qualitative interest (no questions or sign-ups).\n- **Pivot:** interest without purchases means the price, offer or format is wrong. Change one variable.\n- **Double down:** sales at or above threshold with profitable unit economics. Add an adjacent product, a bundle, or a second channel.\n\nIgnore sunk cost. Record the reason for every decision. Retire dead listings to cut clutter, unless keeping them is free and harmless.","tags":["stop","pivot","kill","double-down","sunk-cost"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"internal method.","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"econ-pricing-math","version":1,"category":"unit-economics","title":"Pricing math and price tests","body":"- Contribution per sale = net price − variable costs (support time, refunds).\n- Break-even units = fixed cost ÷ contribution.\n- Raising the price cuts unit sales; raising the price 30% remains profitable unless it loses more than about 23% of units (at near-zero marginal cost).\n\nTest prices sequentially with time blocks or new products. Do not show different prices to similar buyers simultaneously in a deceptive way, and never invent \"original\" prices. Look at revenue per visitor, not conversion rate alone.","tags":["price-test","break-even","contribution","elasticity"],"keywords":[],"factsThatChange":[],"hardRules":[],"sources":[{"text":"CMA207 (OGL) for pricing-practice limits.","urls":[],"licence":"","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"},{"id":"ethics-honest-claims","version":1,"category":"ethics-safety","title":"No deceptive claims, ever","body":"Every statement about a product, its results, its scarcity, your identity or your track record must be true and checkable. Banned:\n- fake scarcity or countdown timers\n- fake \"as seen in\" badges\n- invented sales numbers, user counts or customer testimonials\n- income or results claims you cannot substantiate\n- impersonating people or brands\n\nDeception risks breaking the DMCC unfair-practice rules and the CAP Code, gets accounts closed (Gumroad and Stripe prohibit deceptive marketing), and destroys the fleet's reputation. When unsure, under-claim.","tags":["honesty","deception","scarcity","testimonials"],"keywords":[],"factsThatChange":[],"hardRules":["Deception risks breaking the DMCC unfair-practice rules and the CAP Code, gets accounts closed (Gumroad and Stripe prohibit deceptive marketing), and destroys the fleet's reputation. When unsure, under-claim."],"sources":[{"text":"CMA207 (OGL); ASA (link only); https://gumroad.com/prohibited (link only)","urls":["https://gumroad.com/prohibited"],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"ethics-ai-disclosure","version":1,"category":"ethics-safety","title":"Truthful AI disclosure","body":"- If anyone sincerely asks whether they're dealing with an AI, say yes, plainly.\n- Disclose AI involvement where a platform requires it (Etsy listings) or where buyers would reasonably expect to know, such as \"written with AI assistance and reviewed\".\n- Never present an AI agent as a named human, claim human credentials, or fake human testimonials.\n- Use bot or automated labels where platforms provide them.\n- Disclosure does not excuse poor quality: AI-assisted products must still be accurate and useful.","tags":["ai-disclosure","transparency","bot-label"],"keywords":[],"factsThatChange":[{"fact":"platform AI-disclosure rules. Etsy: SNIPPET; others UNVERIFIED. Verify at https://www.etsy.com/legal/creativity/","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":["https://www.etsy.com/legal/creativity/"]}],"hardRules":["Never present an AI agent as a named human, claim human credentials, or fake human testimonials."],"sources":[{"text":"Etsy (link only); X automation rules (link only)","urls":["https://www.etsy.com/legal/creativity/"],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"ethics-platform-tos","version":1,"category":"ethics-safety","title":"Respect platform terms and account integrity","body":"- Read each platform's terms and prohibited list before listing.\n- One account per approved identity. No ban evasion, duplicate accounts, scraping against ToS, automated engagement or review manipulation.\n- If a rule is ambiguous, ask the platform's support or the operator; do not test the boundary.\n- A suspended payment account can freeze funds for months, so compliance protects survival.\n- Account creation, KYC and anything involving the operator's legal identity, keys or money movement requires operator approval and is never done by agents on their own.","tags":["tos","account-integrity","ban-evasion","approval"],"keywords":[],"factsThatChange":[{"fact":"platform terms (see the channel entries).","lastChecked":"2026-10-08","confidence":"unverified","staleAfterDays":90,"verifyAt":[]}],"hardRules":["Read each platform's terms and prohibited list before listing."],"sources":[{"text":"platform terms (link only)","urls":[],"licence":"link only","usage":"link-only"}],"lastReviewed":"2026-10-08"},{"id":"ethics-customer-fairness","version":1,"category":"ethics-safety","title":"Treat customers fairly","body":"- No dark patterns: no pre-ticked add-ons, hidden fees, cancellation obstacles or guilt-trip opt-outs.\n- Honour statutory rights and your own published policies.\n- Keep customer data private; never reuse it for unrelated purposes.\n- Don't target vulnerable groups with high-pressure sales.\n- If you get something wrong, fix it and refund proactively.\n\nLong-term survival depends on repeat buyers and reputation more than on any single sale.","tags":["dark-patterns","fairness","vulnerable","privacy"],"keywords":[],"factsThatChange":[],"hardRules":["Don't target vulnerable groups with high-pressure sales."],"sources":[{"text":"CMA207 (OGL); legislation.gov.uk (OGL)","urls":[],"licence":"OGL","usage":"paraphrase-with-attribution"}],"lastReviewed":"2026-10-08"}]} as const;
